import{d as e,l as t,o as n,u as r}from"./hooks-BvnSFNkU.js";import{a as i,i as a}from"./common-hHC2TKlh.js";var o=r(),s=[{id:`entrar`,title:`Entrar y dispositivos`,items:[[`Cómo se entra`,`Mail, contraseña y el código de 6 dígitos de tu app de autenticación. Además, solo entran los dispositivos aprobados: tu PC y tu celular.`],[`Llave de acceso`,`Todavía no están disponibles: llegan cuando lo estén. Mientras tanto, Seguridad dice «Llaves de acceso: todavía no disponibles» y se entra y se confirma con el código de 6 dígitos. Cuando lleguen, en Seguridad → Llaves de acceso vas a sumar la llave de tu celular o tu compu: te pide el código de 6 dígitos y después la huella, la cara o el PIN del dispositivo. Desde ahí, al entrar aparece «Entrar con mi llave» en lugar de escribir el código, y las acciones sensibles se confirman con «Usar mi llave». El código sigue sirviendo siempre. Si aparece una llave que no sumaste desde el panel, ninguna llave sirve hasta que la quites. Con el hard lockdown no se entra con la llave: va el código de rescate. Desde la app Android, por ahora, el código.`],[`Autenticadores de afuera`,`Si en tu cuenta aparece una app autenticadora o una llave que no se configuró desde el panel, Seguridad lo muestra arriba, en «Autenticadores de afuera». No sirve para entrar ni para confirmar nada: quitalo desde ahí (te pide el código de 6 dígitos y no se puede durante un lockdown) y, si no sabés de dónde salió, cambiá tu contraseña y revisá tus dispositivos. Si al entrar el panel te pide configurar tu app autenticadora de nuevo, escaneá el código nuevo: el de antes deja de servir y a todos les llega el aviso.`],[`Soft lockdown`,`Si hay intentos de ingreso sospechosos, el panel se cierra a los dispositivos que no están autorizados y te avisa. Mientras dure, lo de todos los días sigue andando y lo riesgoso aparece deshabilitado con «Bloqueado mientras dure el lockdown». En Seguridad → Lockdown ves qué pasó y lo levantás con tu contraseña.`],[`Hard lockdown`,`Cierra el panel entero y todas las sesiones de todos. Lo prendés con «Hard lockdown», abajo en el menú, o en Seguridad → Lockdown: solo pide «¿Seguro?». Para volver a entrar hace falta tu contraseña y tu código de rescate, desde un dispositivo autorizado; ahí ves qué pasó, decidís qué hacer con el dispositivo y lo levantás. Mientras tanto podés usar el panel sin levantarlo («Usar el panel mientras tanto»), con lo riesgoso bloqueado. Desde la app no se entra hasta que se levante.`],[`Protocolo Cerberus`,`El modo de emergencia para cuando sospechás un ataque grande, más fuerte que el hard lockdown. Está en Seguridad, debajo de Lockdown. Lo prende la mayoría de las personas del panel (con dos personas, las dos). Cada una vota con su contraseña y su código, y cada voto les avisa a las demás. Si la mayoría no llega a tiempo, la votación vence. Al prenderse se cierra el panel entero y los sitios quedan protegidos con su resguardo y su modo defensa. El portal de clientes y los formularios de la página (presupuestos, reuniones, consultas y pedidos de la vidriera) muestran que hay un mantenimiento. Para entrar mientras dura usás tu código de rescate, como en el hard lockdown, y el panel muestra solo cómo están los sitios y quién hizo qué. Se apaga votando igual, con tu contraseña y tu código. El resguardo y el modo defensa de los sitios siguen prendidos después y los levantás a mano, sitio por sitio. Todo queda en quién hizo qué. En la app ves si está prendido.`],[`Me robaron un dispositivo`,`Si en el hard lockdown elegís «Me lo robaron», ese dispositivo queda revocado para siempre y vas a poner una contraseña y un autenticador nuevos antes de volver a usar el panel.`],[`Código de rescate`,`Uno por persona. Lo generás en Seguridad → Recuperación y notificaciones y se muestra una sola vez: guardalo fuera de la compu y del celular. Sirve una vez, para volver a entrar con el panel en hard lockdown o para sumar un dispositivo tuyo sin aprobación.`],[`Un dispositivo nuevo`,`Después del código, pedís acceso para ese dispositivo y lo aprobás desde uno que ya esté aprobado, en Seguridad. Con tu código de rescate se aprueba solo.`],[`Si perdés algo`,`Desde otro dispositivo, en Seguridad → Dispositivos, revocá el que perdiste: se cierran sus sesiones al instante. Un revocado se saca de la lista con «Eliminar». Si tenía una llave de acceso, quitala en Seguridad → Llaves de acceso. Qué hacer paso a paso (el celular, la PC, todo) está en Seguridad y recuperación, abajo en el menú.`],[`Personas con acceso`,`En Seguridad sumás a un socio con su nombre y su mail: le llega un mail con una contraseña temporal y los pasos para entrar. Ve y usa todo el panel menos esa lista, con sus propios dispositivos y códigos.`],[`Aprobar a un socio`,`Cuando pide acceso desde un dispositivo te llega un aviso («Lautaro pidió acceso desde…»). En Seguridad → Dispositivos aparece con su nombre: aprobalo solo si sabés que es él. También puede aprobarse solo desde otro dispositivo suyo ya autorizado o con su código de rescate.`],[`Desactivar a alguien`,`«Desactivar» en Personas con acceso lo saca del panel al instante en todos sus dispositivos. «Reactivar» le devuelve el acceso con los mismos dispositivos. Solo vos podés aprobar o revocar dispositivos de otros.`],[`Cambiar la contraseña`,`En Seguridad → Cambiar contraseña: la actual, la nueva dos veces y el código de 6 dígitos. Se cierran tus otras sesiones.`],[`Contraseña de coacción`,`Se pone, se cambia o se saca en Seguridad → Contraseña de coacción, con tu contraseña y el código de 6 dígitos. Para qué sirve y cuándo usarla está en Seguridad y recuperación, abajo en el menú.`],[`Acciones peligrosas`,`Forzar el respaldo, volver a producción, poner en mantenimiento, reiniciar o apagar un servidor, crear un administrador de un turnero, sumar o desactivar a una persona, marcar un lugar como nuestro en «Desde dónde se usan las claves», abrir la Bóveda, abrir Seguridad y recuperación, dar de alta un sitio con direcciones o Railway, dar de baja un sitio o cambiarle las direcciones, Railway, el cliente, dónde corre, la base, el latido, las copias, los umbrales o los datos de la PC, prender «Levantar en mi PC si se cae», generar un sitio desde una plantilla, cambiar «Cómo pagar» o el nombre del remitente de los mails, borrar un cobro, cambiar la regla de datos clínicos de un turnero e importar una copia del panel: vuelven a pedir el código (o tu llave, cuando estén disponibles) si pasaron más de 5 minutos.`],[`Notificaciones y app`,`En Seguridad activás las notificaciones del dispositivo. En el celular, desde el menú del navegador, «Agregar a pantalla principal» lo deja como una app.`]]},{id:`calendario`,title:`Calendario`,items:[[`Qué junta`,`Las reuniones (en violeta, con su hora) y todo lo que vence o se entrega: cobros pendientes (y los mensuales de los contratos y los abonos que todavía no se generaron, marcados «Estimado»), etapas de los roadmaps con fecha prevista, vencimientos de certificados y dominios, sitios con la copia atrasada (y la bóveda o la copia del panel, si se atrasan) y presupuestos que esperan respuesta y vencen. Cada cosa lleva a la pantalla donde se resuelve: Cobros, la ficha del cliente, el sitio o el presupuesto.`],[`Cómo se lee`,`Arriba, el mes con las flechas y «Hoy»; los botones de colores eligen qué mostrar. En la grilla, cada día muestra hasta tres cosas (el resto, con «más»); tocando el número del día ves solo ese día. Al lado (o abajo), la agenda: lo atrasado primero, en rojo, y después de hoy en adelante. En el celular la grilla no aparece: queda la agenda.`],[`Vencido y atrasado`,`Un cobro sin pagar después de su vencimiento, una etapa sin entregar después de su fecha, un certificado o dominio vencido, o una copia buena más vieja que su frecuencia (y que la antigüedad máxima del sitio). Se van solos cuando se resuelven.`],[`Aviso del día anterior`,`Todos los días a las 9 te llega al celular lo que tenés mañana (las reuniones con su hora) y lo que vence o se entrega, una sola vez. Se apaga y se prende con «Aviso el día anterior», arriba a la derecha del Calendario. En el Resumen, «Próximos 7 días» muestra lo de la semana.`],[`Credenciales`,`Cuándo vence cada clave o token de los servicios, con una llave. Te avisa al celular 30 días antes, 7 días antes y el día anterior; si se pasa la fecha, queda como vencida. Tocala para abrir «Renovar» y poner el nuevo vencimiento (o «Sin vencimiento»). La lista para agregar, editar o borrar está en Seguridad → Credenciales: solo nombres y fechas, nunca el valor de una clave.`]]},{id:`reuniones`,title:`Reuniones`,items:[[`Qué son`,`Videollamadas de Jitsi Meet: gratis, sin cuenta y sin instalar nada (se abren en el navegador; en el celular conviene la app Jitsi Meet). Cada una tiene su propio link largo y al azar, que se genera solo.`],[`Desde la página`,`En la portada, debajo de «Sistema de turnos», «Agendá una reunión»: la persona elige un día y un horario libre (de lunes a viernes, en punto de 9 a 17 de Argentina, con 24 horas de anticipación y hasta tres semanas; nunca uno que se pise con otra reunión) y deja su nombre, mail, empresa y de qué quiere hablar. Le llega un mail para confirmarla: hasta que toca «Confirmar reunión» no se agenda nada, el horario sigue libre y a vos no te llega nada (si no la confirma, se borra sola). Al confirmar ve la confirmación con el link y le llega otro mail con el link, «Agregar a Google Calendar» y el evento (.ics) para su calendario; a vos, un mail con el .ics y un aviso al celular. Si el mail es de un cliente (el de su ficha o el de una cuenta del portal), queda en ese cliente. Tiene topes por conexión, por mail y por día: si se llega al del día, la página deja de tomar reservas hasta el otro día, muestra el mail del estudio para que escriban y te llega un aviso al celular. Te avisa de las primeras 20 reuniones confirmadas del día; si hay más, te llega un solo aviso y las ves en el calendario.`],[`Crear una a mano`,`Calendario → «Nueva reunión»: con quién (un cliente de la lista, que completa su contacto, u otra persona), día, hora (de Argentina), duración, tema, notas internas y el idioma de los mails. Con «Mandarle el mail» le llega lo mismo que a quien agenda desde la página. No deja pisar otra reunión ni usar el mail de otro cliente.`],[`El detalle`,`Tocando una reunión en el Calendario (o en «Próximos 7 días») ves con quién, cuándo, el tema, el cliente, si se le mandó el mail y tus notas. «Entrar a la llamada» abre el link; «Copiar link» lo copia. «Marcar hecha» la deja marcada en el Calendario; «Cancelar reunión» (te pregunta si estás seguro) la saca del Calendario, libera el horario y le avisa por mail a la persona con el evento cancelado para su calendario.`],[`En el portal`,`Si la reunión es de un cliente, la ve en su portal, en «Próximas reuniones», con el día, la hora, el tema y el botón para entrar, hasta que termina.`],[`Mails y el código`,`Si el mail de la reunión no está en la ficha de su cliente (contacto, cobros, reportes o una cuenta del portal), mandarle la confirmación o la cancelación te pide el código de 6 dígitos. Las que agendaron desde la página, no. Entre reuniones y respuestas a pedidos salen hasta 50 mails por día desde el panel: pasado eso, no sale ninguno más hasta el día siguiente y te llega un aviso.`]]},{id:`sitios`,title:`Sitios`,items:[[`Estados`,`Funcionando, Degradado (lento o con errores), Caído, Atiende tu PC o «Atiende la PC de …» (una compu de respaldo atiende: dice cuál, y «tu PC» solo si es la tuya), Uniendo datos, Unión fallida y Mantenimiento. Si está Caído o Degradado, la tarjeta dice por qué. Puede ser el servidor, la base o la web, por ejemplo «La web no abre. El servidor responde bien.».`],[`Barras`,`Cada barra es un minuto, con la API y la web juntas. Verde si anduvieron, amarillo si falló un chequeo suelto, rojo si se cayó. La disponibilidad cuenta solo lo rojo.`],[`Pasar al respaldo a mano`,`En Respaldo y copias, «Pasar al respaldo (A)» y «con copia (B)» aparecen solo en los sitios que una compu de respaldo sabe levantar. En los sitios en Supabase o estáticos no están.`],[`Arriba del sitio`,`«Abrir sitio» abre la página; «Search Console», cómo le va en Google (qué buscan para llegar, clics, apariciones y páginas), con tu cuenta de Google. Si el sitio todavía no está en tu Search Console, primero hay que agregarlo y verificarlo. «Salud» abre el chequeo del servidor.`],[`Estado`,`Disponibilidad, el tiempo de respuesta (medido cada 5 minutos, para cada sitio por separado), el último latido, cuándo vence el certificado de cada dirección, los recursos y los topes de las APIs.`],[`Web que no carga`,`Si la web responde pero no carga (por ejemplo, un deploy que la dejó en blanco), arriba de Estado un aviso dice qué falla. Si sigue así 10 minutos, se abre un incidente y te llega un aviso al celular, una sola vez aunque lo cierres. Se cierra solo cuando vuelve a cargar.`],[`Recursos`,`En Estado, una tarjeta por servicio de Railway (el servidor y la base): la memoria de ahora y el pico de 7 días contra el límite, la línea de la semana y cuánto cuesta esa memoria por mes. En la base, además, qué parte de las lecturas sale de memoria, cuánto ocupa la memoria de MySQL (buffer pool) y las conexiones, que llegan con cada copia. Cada servicio lleva un veredicto con el porqué en una frase: «Sobra» (se puede achicar para ahorrar), «Bien», «Al límite: conviene subir» o «Falta memoria». Se mide una vez por hora. Los sitios que no están en Railway dicen «Sin datos de recursos».`],[`Aviso de memoria`,`Cuando un servicio pasa a «Al límite» o a «Falta memoria», se abre un incidente (sin aviso al celular) y el sitio lleva una marca en Sitios y en el Resumen. No se repite mientras siga igual, aunque lo cierres; si empeora, avisa otra vez. Cuando vuelve a «Bien», se cierra solo.`],[`Topes de las APIs`,`En Estado, cuánto gastó el sitio de cada servicio con tope gratis, como los mails o el asistente. Todo junto está en Topes.`],[`Servidor`,`Los deploys de Railway: ver registros, reiniciar, volver a publicar, volver a la versión anterior o apagar. Abajo, el gasto del mes contra el presupuesto.`],[`Respaldo y copias`,`Si una compu de respaldo levanta el sitio cuando se cae, sus copias, la última prueba de restauración y el reporte de la unión de datos.`],[`Avisos`,`Mensajes que ven solo los admins de ese sitio, arriba de su panel y en su campanita. Podés pedir que confirmen que lo leyeron. Uno retirado o vencido se puede borrar del historial con «Borrar»; uno vigente, primero se retira.`],[`Seguridad`,`Lo que reporta el sitio: cuentas bloqueadas, intentos fallidos de ingreso, cambios de rol, cambios de reglas y lo que hizo su modo defensa (si se prendió solo, y cada tanto un resumen de lo que frenó).`],[`Modo defensa`,`Arriba de todo en la pestaña Seguridad. Frena el tráfico sospechoso de inmediato: usalo si el sitio está bajo un ataque de bots. Se prende y se apaga con un «¿Seguro?», sin el código de 6 dígitos, y el sitio se entera en su próximo latido (también la compu de respaldo, si está atendiendo). Mientras está prendido, el sitio lleva la marca «Modo defensa» en su encabezado y en Sitios. Debajo, una línea dice qué está pasando en el sitio: prendido desde el panel, si se prendió solo (y hasta cuándo) o apagado, y si por ahora solo mira y no frena. Si el sitio tarda en aplicar lo que pediste, dice «Esperando que el sitio lo aplique». También está en Seguridad, en «Modo defensa de los sitios». Durante un lockdown se puede prender, pero no apagar. Queda en Seguridad, en quién hizo qué.`],[`Resguardo`,`Solo en los turneros. En Seguridad, arriba de todo («Resguardo de los turneros», todos juntos), y en la pestaña Seguridad de cada turnero. Frena en el sitio los cambios importantes (altas, roles, bajas, exportar, configuración) y deja andar lo de todos los días. Se prende con tu contraseña y se levanta con el código de 6 dígitos. El sitio también puede prenderlo solo ante un acceso sospechoso, y «Levantar resguardo» saca también eso. El panel lo prende solo si ve algo grave de ese sitio, y te avisa. Mientras está prendido desde el panel, el sitio lleva la marca «Resguardo» en su encabezado y en Sitios. Una línea dice qué está pasando en el sitio. Mientras el sitio aplica lo que pediste (menos de un minuto) dice «Prendiéndolo» o «Levantándolo», y si tarda más, «Esperando que el sitio lo aplique». Siempre hay un solo botón, el que corresponde. Durante un lockdown se puede prender, pero no levantar. Mientras está prendido, el panel vigila ese sitio más de cerca y te manda al celular cada evento suyo, también si deja de latir.`],[`Bloqueo de acceso`,`En la pestaña Seguridad de cada turnero, para cuando sospechás que entró alguien y no sabés con qué cuenta. Los admins (y si querés, los profesionales) quedan afuera y se cierran sus sesiones hasta que lo levantes. Se bloquea con tu contraseña, también en un lockdown; levantarlo pide el código y no anda en un lockdown. Mientras dura, el sitio lleva la marca «Acceso bloqueado» y cada intento de entrar queda en sus eventos.`],[`Cerrar sesiones de admins y profesionales`,`En la tarjeta del resguardo. Elegís admins, profesionales o los dos y confirmás con tu contraseña. Todos los que elegiste tienen que volver a ingresar. Los pacientes no se tocan. Anda también durante un lockdown, y queda en quién hizo qué.`],[`Errores`,`Fallas del servidor agrupadas, con cuántas veces pasaron. «Marcar resuelto» las cierra; si vuelven, se reabren solas.`],[`Reportes`,`Problemas que te mandan los admins de ese sitio con «Reportar un problema».`],[`Instalación`,`Solo en los turneros: administradores y reglas del consultorio. Crear un administrador te pide el código de 6 dígitos. La regla de datos clínicos (su valor o su bloqueo) la cambia solo el dueño del panel, con el código. Los cambios de reglas quedan en borrador hasta «Guardar cambios», que te pregunta si estás seguro.`],[`Apagar el segundo paso de un administrador`,`En Instalación, para el administrador que perdió el teléfono y sus códigos de respaldo. Entra solo con su contraseña, se cierran sus sesiones y les llega un mail a todos los administradores. Lo hace el dueño del panel, con el correo escrito y su código de 6 dígitos.`],[`Probar endpoints`,`Pedidos a la API del sitio desde el servidor del panel, con lo que esperás que responda. Se pueden guardar y repetir. Una dirección que no es de un sitio cargado en el panel te pide el código de 6 dígitos, y las de una red interna no se prueban.`],[`Contrato y pagos`,`Pago inicial (con seña y cuotas si querés) y mensual. El mensual puede ser fijo (lo ajustás con «Cambiar precio») o lo que consumió el proyecto en Railway, con un mínimo. Si el cliente pagó solo el desarrollo, elegí «Pago único»: se cobra una vez (en pesos o dólares, también con seña y cuotas), nunca genera mensuales ni cobros de Railway, no suma al ingreso recurrente y el cliente no entra en los informes mensuales. Si el sitio no tiene cliente, asignáselo en Ajustes para que lo cobrado aparezca en Clientes.`],[`Ajustes`,`Direcciones, chequeos, cada cuánto se copia, la antigüedad máxima de la copia y el presupuesto de Railway del sitio. «Mostrar su estado en vivo en la home» lo suma al tablero de la portada, que muestra hasta 6 sitios con sus barras y del resto solo cuántos funcionan: los «destacados» van primero y después los que llevan más tiempo. «Token nuevo» genera otro token para el sitio: el de antes sigue andando un rato, hasta que el sitio empieza a usar el nuevo, así no se corta mientras lo cargás. Cambiar las direcciones, Railway, el cliente, dónde corre, la base, el latido, las copias o el presupuesto de Railway, y «Dar de baja», pueden pedirte el código de 6 dígitos; el nombre, las notas y lo de la home, no. «Estado» en «En desarrollo» es para un sitio que todavía no se publicó. Es puertas adentro: no se chequea ni se copia, se cierran sus incidentes y el cliente no lo ve en su portal (ni su estado, ni sus avisos, ni para pedidos). Al publicarlo, pasalo a Activo y recién ahí le aparece. Cambiar el estado pide el código. Si un sitio deja de copiarse (en desarrollo, pausado, de baja o «Sin base») o queda activo sin base, el panel les avisa a todos.`]]},{id:`topes`,title:`Topes`,items:[[`Qué muestra`,`Cada servicio gratis con tope, con lo usado y una barra. Arriba el panel y las cuentas, después cada sitio.`],[`Qué se mide`,`Mails, asistente, bases, archivos, funciones, minutos y espacio de GitHub, la red de Tailscale y el gasto de Railway. Se mide cada hora.`],[`Avisos`,`Desde el 80 % se abre un incidente con aviso al celular, y desde el 95 % otro más urgente. Se cierra solo cuando baja.`],[`Sin medición`,`Abajo, lo que no se puede leer solo y dónde mirarlo.`]]},{id:`caidas`,title:`Si un sitio se cae`,items:[[`Qué hace el panel`,`Si el sitio falla varios minutos seguidos, abre un incidente, te avisa al celular y pide una copia de emergencia.`],[`Una compu lo levanta`,`Solo en los sitios donde lo habilitaste. Si cayó el servidor y la base sigue viva, la compu de respaldo atiende contra esa base. Si cayó también la base, levanta la última copia, salvo que sea más vieja de lo permitido: ahí el sitio pasa a mantenimiento.`],[`Mi PC`,`En Servicios → Mi PC elegís qué sitios se levantan si se caen («Levantar en mi PC si se cae») y ves si cada compu está lista para cada uno: prendida, código del backend, acceso a la base, token del sitio, que los ids de Railway sean los que esa compu ya tiene anotados, Funnel, que la web acepte la dirección de esa compu, copia reciente, prueba de restauración y el último simulacro. Arriba de los sitios elegís de qué compu ver la lista. Prender ese interruptor te pide el código de 6 dígitos; apagarlo, no. Lo que no se puede levantar en una PC (Supabase, sitios estáticos) aparece apagado con el motivo.`],[`Varias compus`,`Además de la PC de Ignacio se pueden sumar otras (por ejemplo la del socio). Si un sitio se cae, lo levanta la primera compu prendida y lista, en el orden de la lista «Compus» (las flechas lo cambian; solo Ignacio, con el código de 6 dígitos). Renombrar o quitar una compu lo hace su dueño o Ignacio, también con el código. Unir los datos y apagar el respaldo los hace siempre la compu que lo atendió. Si esa compu deja de responder mientras atiende, te llega una alerta.`],[`De quién es cada compu`,`Cada compu tiene dueño (la elegís al sumarla y se cambia con «Editar»): quien la usa la ve como «tu PC» y los demás como «la PC de» esa persona; una que no es de nadie del panel (la de la oficina) se ve con su nombre. Así cada uno lee «Atiende tu PC» solo cuando la que atiende es la suya.`],[`Sumar otra compu`,`Mi PC → «Sumar otra compu» te lleva paso a paso: invitar a la persona a la red de Tailscale (entra con su usuario, como miembro: su compu sin etiqueta o «tag», o no llega a las bases que van por la red) y dejarla usar Funnel, el token de lectura de GitHub (una sola vez), el compromiso de confidencialidad que firma la persona (se imprime desde ahí), el nombre de la compu y el código (te pide el de 6 dígitos; vale una hora y una sola vez) con el comando que la persona pega en PowerShell. No hace falta que sepa programar.`],[`Pasarle las claves`,`Cuando la compu nueva aparece, dice «Esperando las claves: todavía no recibe órdenes». «Pasarle las claves» (código de 6 dígitos, con la PC de Ignacio prendida y él frente a ella: la primera vez para cada compu aparece ahí una ventana para aprobarla) hace que esa PC le mande cifradas solo las claves para atender los sitios que puede levantar: el panel nunca las ve. Nunca le pasa el token de la cuenta de Railway, el acceso a Tailscale ni las claves de root de las bases. Cada compu muestra también si guarda las claves cifradas en el disco («Disco protegido»).`],[`Proteger la carpeta de las claves`,`Al terminar, el instalador pide permiso de administrador una sola vez para que Windows Defender vigile la carpeta de las claves («Acceso controlado a carpetas», primero solo anotando). Si la persona dice que no, la compu funciona igual y el instalador deja el comando para hacerlo después; también dice si el disco está cifrado y cómo prenderlo, sin obligar. Cuando el agente baja o actualiza MySQL hay que volver a correrlo (agent/proteger.ps1; en la PC de Ignacio, scripts/ops/proteger-control.ps1).`],[`Trabajar desde otra PC`,`Mi PC → «Trabajar desde otra PC» → «Preparar instalación» te da un comando para pegar en PowerShell en la otra compu. Vence en 30 minutos. Seguí los pasos que muestra. Antes, en tu PC, corré /otra-pc en Claude Code para que tenga lo último. No es lo mismo que «Sumar otra compu», que es para respaldo. Los pasos, en docs/OTRA-PC.md.`],[`Actualización sola`,`Las compus que sumás se actualizan solas cuando publicás una versión nueva del agente (solo si la firmó la PC de Ignacio). Si la versión nueva no llega a reportarse bien al panel (3 arranques o 10 minutos), la compu vuelve sola a la anterior, no la vuelve a bajar y Mi PC lo muestra en «Actualización»: publicá otra versión con el arreglo. La PC de Ignacio no se actualiza sola (corre desde el repo).`],[`La web de cada sitio`,`Cada compu atiende con su propia dirección de Tailscale. Para que la web de un sitio acepte todas, la sesión de ese proyecto suma https://*.<tu-red>.ts.net a su lista permitida y publica la web (con tu OK). La dirección exacta de tu red está en Mi PC → «Sumar otra compu» → «La web».`],[`Simulacro`,`Una prueba de punta a punta sobre un sitio descartable: se lo tira abajo de verdad y se mira que una compu lo levante, atienda por internet y devuelva los datos a producción. El resultado queda en Mi PC.`],[`La vuelta`,`Cuando producción vuelve, la compu que atendió une lo que se cargó mientras atendía y verifica que los datos queden bien. Solo entonces el sitio vuelve a producción.`],[`Unión fallida`,`Si la unión no pasa las verificaciones, el sitio sigue en la compu que lo atiende con una advertencia fuerte. Revisá el reporte en Respaldo y copias, resolvelo con una sesión de Claude y tocá «Ya lo resolví: volver».`]]},{id:`boveda`,title:`Bóveda`,items:[[`Qué es`,`Servicios → Bóveda: el estado de la bóveda cifrada y de la copia diaria del panel, y cada sitio con sus repos y sus cuentas. Te pide el código de 6 dígitos cada vez que la abrís, aunque ya hayas entrado al panel, y cada apertura queda en Seguridad. Si cancelás el código, te ofrece volver a intentarlo.`],[`Las dos copias`,`Una tarjeta para la bóveda y otra para la copia del panel: la última buena, el último intento, el tamaño y el error, si hubo. Si una se atrasa (3 días la bóveda, 2 la copia del panel), se pone en rojo y aparece como copia atrasada en el Calendario y en «Próximos 7 días» del Resumen. Se va sola cuando llega una buena.`],[`Sitios, repos y cuentas`,`Una tarjeta por sitio con sus repos, que se abren en otra pestaña, y con qué cuenta está en cada servicio, más las sesiones abiertas en la PC. Se cargan desde la PC del estudio: si todavía no se cargaron, dice «Sin datos».`],[`Qué tiene y cómo se recupera`,`Está en Seguridad y recuperación, que también pide el código.`]]},{id:`servicios`,title:`Incidentes, reportes, seguridad y copias`,items:[[`Incidentes`,`Todo lo que se rompió o está por romperse: caídas, una web que no carga, copias fallidas, certificados por vencer, gasto de más, errores repetidos. Se cierran solos cuando se arreglan.`],[`Mails que no salen`,`Cada hora el panel revisa en Brevo los mails que no se mandaron o no llegaron. Si Brevo rechaza los del panel o los de un sitio (por ejemplo, porque el remitente no está validado), abre un incidente crítico y te llega al celular. Se cierra solo cuando pasa un día sin rechazos. Si un mail del panel no llegó porque la dirección no existe o está bloqueada, abre un aviso con el asunto y la hora, que cerrás vos.`],[`Reportes`,`Lo que te mandan los admins de los sitios, con captura. «Responder» le llega como aviso, con link a sus reportes y por 7 días, solo a quien reportó; con «Mandarla también a todos los admins», a todos (si el reporte no trae un mail, va a todos). Si el reporte era nuevo, pasa a «En curso». El estado se cambia arriba, en «Estado».`],[`Seguridad`,`Los dispositivos (con de quién es cada uno), tus llaves de acceso (cuando estén disponibles), los autenticadores de afuera (si hay), las personas con acceso, el lockdown, el Protocolo Cerberus, el modo defensa de cada sitio, tu código de rescate, cambiar la contraseña, tu contraseña de coacción, el historial de accesos, quién hizo qué en el panel y los eventos de seguridad de todos los sitios. De un mismo sitio llegan como mucho 5 avisos de seguridad cada 10 minutos; el resto se guarda igual y llega un resumen al final.`],[`Modo defensa de los sitios`,`En Seguridad, debajo de Lockdown: el interruptor del modo defensa de cada sitio que lo tiene, con la misma línea que en su pestaña Seguridad (prendido desde el panel, prendido solo y hasta cuándo, apagado, o esperando que el sitio lo aplique). El nombre lleva a su pestaña Seguridad. Se prende y se apaga igual que ahí, con un «¿Seguro?»; durante un lockdown, lo prendido no se puede apagar. Si no aparece ningún sitio, es que todavía ninguno tiene modo defensa.`],[`Eventos de seguridad`,`En Seguridad (y en la pestaña Seguridad de cada sitio), lo que reportan los sitios y las compus, del más nuevo al más viejo. Tocá uno para ver qué pasó. En «Ingresos extraños frenados» y en los resúmenes del modo defensa dice entre qué horas fue, cuántos pedidos se frenaron, por qué motivo y qué significa cada uno, y si hace falta hacer algo. Cuando un admin o un profesional de un turnero entra desde un dispositivo nuevo, el sitio le pregunta por mail si fue él. Llega «Ingreso raro avisado» y después su respuesta, «fui yo» o «no fui yo». Con «no fui yo» el sitio ya cerró las sesiones de esa cuenta y, si es admin, prendió el resguardo; el detalle dice qué te queda por hacer. «Revisado» (o «Marcar revisado» en el detalle) lo saca de «Sin revisar».`],[`Desde dónde se usan las claves`,`En Seguridad, cada clave que le habla al panel (el token de cada sitio, la de cada compu y la del corredor de copias; la tuya dice «Clave de tu PC») con los lugares desde donde llegó, cuándo y cuántas veces. Si aparece un lugar nuevo queda en Eventos de seguridad, y si algo es grave te llega al celular. «Es nuestro» marca un lugar como conocido: pide el código de 6 dígitos y no se puede durante un lockdown. Marcalo solo si sabés que es tuyo.`],[`Rotar y controlar claves`,`En Seguridad, debajo del modo defensa y de «Autenticadores de afuera». «Controlar claves» revisa que cada clave ande y esté igual en todos los lugares donde se usa, sin cambiar nada, y muestra las que necesitan atención. Debajo, las claves que se pueden rotar desde acá, cada una con su «Rotar» y cuándo se rotó por última vez. Rotar te pide el código de 6 dígitos y solo lo ves vos. Lo hace tu PC, así que tiene que estar prendida. Una orden a la vez, y nada durante un lockdown.`],[`Claves expuestas`,`Si una compu encuentra una de las claves donde no debe (en un proyecto o en una página publicada), te avisa al celular y aparece en Seguridad como «Clave expuesta», con el nombre de la clave y dónde está, nunca la clave. Avisa una sola vez por lugar: vuelve a avisar solo si después de resolverse aparece de nuevo. Se resuelve sola cuando ya no está ahí o cuando cambiás la clave. Arriba de la lista dice cuándo revisó cada compu por última vez. En cada compu, un commit que lleva una clave se frena antes de guardarse y te dice cuál y en qué archivo.`],[`Páginas de GitHub`,`Una vez por día el panel revisa las páginas publicadas en tu cuenta de GitHub. Si aparece una sin dominio propio, te avisa una sola vez al celular con el nombre del repo y queda en Seguridad como «Página sin dominio propio», ya revisada. Si no la publicó nadie de ustedes, revisala. No frena nada y se cierra sola cuando pasa a su dominio.`],[`Código publicado`,`Cuando se publica código nuevo del panel te llega un aviso al celular. Si no lo publicó nadie de ustedes, revisalo. El detalle está en la guía protegida.`],[`Claves trampa`,`En Eventos de seguridad, una línea dice cuántas claves trampa hay puestas y cuándo se probó una por última vez. Si alguien usa una, te llega un aviso grave al celular y por mail con su código (T1, T2…), desde dónde y a qué hora, y queda en Eventos de seguridad como «Clave trampa usada». «Probar» hace lo mismo de punta a punta con un aviso marcado PRUEBA, sin prender nada (conviene una vez por mes). Qué es cada código está en la guía protegida.`],[`Librerías con fallas conocidas`,`En Seguridad, las librerías que usan tus repos de GitHub y tienen fallas de seguridad conocidas, según GitHub: por repo, cuántas hay de cada gravedad, y con «Ver la lista» cuáles son, si son solo de desarrollo, con qué versión se arreglan y el link a GitHub. Los repos de clientes dicen de quién son. Se revisa cada 6 horas. Si aparecen graves nuevas, te llega un solo aviso al celular por revisión y queda en Eventos de seguridad como «Librerías con fallas graves». Cuando en GitHub se arreglan o se descartan, desaparecen solas. Si GitHub no se puede leer por un tiempo (por ejemplo, porque venció el permiso), queda «Alertas de GitHub sin revisar», sin aviso al celular.`],[`Revisión semanal`,`En Seguridad, debajo de «Rotar y controlar claves» (solo para el dueño del panel). Cada lunes a la mañana tu PC revisa la semana (Seguridad, las copias y las compus) y deja un resumen: «Todo en orden» o cuántas cosas hay para mirar, cada una con qué hacer. Te avisa al celular con el link a la tarjeta (desde la app se abre en el navegador). Si la PC estaba apagada el lunes, la hace apenas la prendés; si una semana no llega, la tarjeta lo dice. Las anteriores quedan abajo, con «Ver». «Minimizar» la deja en una línea hasta que llega la próxima, que se abre sola. Si alguna clave lleva más de 3 meses sin rotar, la revisión lo sugiere. Es opcional: «Ignorar por 3 meses» la saca hasta entonces.`],[`Copias`,`Todas las copias, cifradas. Se hacen cada 2 horas, se guardan las últimas 12, una por día por 14 días y una por mes por 6 meses. Todos los domingos se prueba restaurar una, también la de los sitios en Supabase.`],[`Avisos a admins`,`Lo mismo que la pestaña Avisos, pero para varios sitios a la vez. «Borrar» en un aviso retirado o vencido lo saca del historial (con quién lo leyó; si respondía a un reporte, el reporte queda), y «Borrar los vencidos» borra todos los que ya no están vigentes de una vez. Los dos piden «¿Seguro?» y quedan en Seguridad, en quién hizo qué.`],[`Qué se borra solo`,`Para que nada crezca para siempre: los eventos de seguridad (y las claves expuestas ya resueltas) a 1 año, las copias fallidas o ya borradas del almacenamiento a 1 año (nunca una buena), las órdenes a las compus terminadas a 6 meses, los informes mensuales descartados y las revisiones semanales a 1 año y el registro de avisos del Calendario a 3 meses. Los incidentes, la auditoría, los avisos y todo lo comercial no se borran solos; las listas largas se ven de a partes con «Ver más».`],[`Estado del mundo`,`Lo que informan Railway, Supabase, Cloudflare, AWS, GitHub, Google, Brevo y Tailscale en sus páginas de estado, más Steam (que no tiene página oficial: se prueba que respondan su API, la tienda y la comunidad). De Cloudflare solo cuenta lo que usamos, el DNS de los dominios y el TURN: sus problemas en otros productos o en centros de datos sueltos no lo ponen en amarillo ni en rojo. Te avisa al celular si se cae, aunque sea en parte, uno del que dependés directo (Cloudflare también, por el DNS), o si uno de los grandes tiene una caída grave.`]]},{id:`negocio`,title:`Negocio`,items:[[`Clientes`,`Datos de contacto, sus sitios, cómo se le cobra (abono, mensual del contrato, «Pago único» o por proyecto), lo cobrado y la deuda. El abono vence el día que elijas, desde el mes que elijas; antes de ese mes no se genera ni figura en el calendario. En «Mails al cliente», si le llega el informe mensual y los recordatorios de pago, y a qué mail. Arriba, sus roadmaps; a la derecha, sus proyectos y las cuentas de su portal. Cambiar sus mails o el recordatorio, crear un cliente con mail (también con «Convertir en cliente») y borrarlo pueden pedirte el código de 6 dígitos.`],[`Idioma de los mensajes`,`En la ficha del cliente (a la derecha, o en «Editar» → «Mails al cliente»): Castellano o English. Con English, todo lo que recibe y ve sale en inglés: los mails del portal (bienvenida y contraseña nueva), las respuestas a sus pedidos, el presupuesto y su confirmación, el informe mensual, los cobros y los recordatorios, el aviso a los admins de sus sitios cuando respondés un reporte, su portal y la página del presupuesto, con montos y fechas en formato inglés. Lo que escribís vos (notas, respuestas, etapas, conceptos a mano) va como lo escribas: para ese cliente, escribilo en inglés; las pantallas te lo recuerdan. «Cómo pagar, en inglés» se carga en Informes (vacío: sale el de castellano). Un presupuesto sin cliente sale en castellano.`],[`Pedidos de clientes`,`Lo que te piden los clientes desde su portal: un cambio, un problema o una consulta, con capturas o PDF. El número del menú cuenta los que te esperan (nuevos, o con un mensaje del cliente después de tu última respuesta); te llega un aviso al celular y un mail. En cada pedido ves la conversación y los archivos, respondés (también con archivos) eligiendo cómo queda: en curso, esperando al cliente o resuelto, y cambiás el estado cuando quieras. Al cliente le llega un mail con el enlace (como mucho uno cada media hora por pedido). «Sumar al roadmap» crea una etapa planificada con lo acordado en un roadmap de ese cliente. En la ficha del cliente, «Pedidos del portal» muestra los últimos.`],[`Cobros`,`Todo lo cobrado y lo pendiente. «Enviar por mail» le manda al cliente el detalle del cobro, con vista previa antes, a uno de los mails de su ficha (para mandarlo a otro, sumalo antes en Clientes). Borrar un cobro puede pedirte el código de 6 dígitos; «Deshacer» lo vuelve a cargar. Cambiar el concepto o las notas de un cobro pendiente que ya mandaste o que va a salir en un recordatorio, también.`],[`Informes`,`El día 1 se arma un borrador del informe mensual de cada cliente que lo tenga activado. Lo revisás tal cual le llega (en su idioma), le sumás una nota y lo mandás a uno de los mails de su ficha, o lo descartás. Si le cambiaste el idioma después de armarlo, te lo avisa y sale en el idioma nuevo. Los sitios de pago único no tienen mantenimiento: no entran en el informe, y un cliente que solo tiene esos no tiene informe.`],[`Finanzas`,`Ingresos y gastos por mes, en pesos, con la cotización del dólar del día.`],[`Consultas`,`Lo que llega por el formulario de contacto de la página. Desde una consulta, «Armar presupuesto» abre un presupuesto nuevo con sus datos.`]]},{id:`proyectos`,title:`Proyectos (desarrollo)`,items:[[`Qué es`,`Negocio → Proyectos: cada cosa que estamos desarrollando o manteniendo, con su iteración en curso, un tablero de tareas, lo que dice el cliente desde su portal y notas para los dos. No es el Portfolio (eso es lo que muestra la página pública).`],[`La lista`,`Muestra los activos (en desarrollo y en producción); los filtros de arriba muestran los pausados, los terminados o todos. Cada tarjeta tiene la iteración en curso con su cinta de avance (de lo hecho a lo que falta empezar) y los días que quedan, el último pedido del cliente y cuántos te esperan. El número del menú cuenta los pedidos del portal que esperan tu respuesta en proyectos activos (cada pedido una vez, aunque toque a dos proyectos).`],[`Crear uno`,`«Nuevo proyecto» o, ya completado, desde la ficha de un cliente (Proyectos → «Crear proyecto»), desde un sitio («Crear proyecto» arriba). Al activar un presupuesto aceptado se crea el suyo. Cliente, sitio, roadmap del portal y presupuesto son opcionales; si elegís uno, se completa lo demás. Cargá el enlace de GitHub y, si querés, la carpeta en la PC.`],[`Arriba del proyecto`,`«Repositorio» abre GitHub en otra pestaña; «Sitio en producción», el sitio; «Ver como el cliente», su portal tal cual lo ve. Abajo del título, el cliente, el sitio del panel y la carpeta con «Copiar».`],[`Iteraciones`,`Una iteración tiene objetivo, fechas y, si querés, la etapa del roadmap del cliente que entrega. Nace planificada; «Arrancar» la pone en curso (hay una sola en curso por proyecto) y, si su etapa estaba planificada, el cliente la ve «En curso». Arriba ves su avance, los días que quedan y el burndown (lo pendiente por día contra la línea ideal; en puntos si las tareas tienen estimación).`],[`Cerrar una iteración`,`«Cerrar iteración» te pregunta qué pasa con lo que no se terminó: vuelve al backlog o pasa a la siguiente (una planificada o una nueva), en la misma columna, y si arrancás la siguiente en ese momento. Podés escribir qué se hizo. Si estaba atada a una etapa del roadmap, te ofrece marcarla entregada (no lo hace sola). Una cerrada queda como historia: no se reabre, no se borra y sus tareas no se mueven.`],[`Tablero`,`Backlog (todo lo que falta, sin iteración) · Sprint backlog (lo que entra en la iteración) · En curso · Revisión · Hecho. Arrastrá las tareas con el mouse; con el teclado, Alt + flechas (izquierda y derecha cambian de columna, arriba y abajo el orden); en el celular, el menú ⋯ de cada tarea. «Agregar tarea» al pie de cada columna la carga ahí mismo (Enter guarda y podés seguir). Arriba elegís qué iteración mirar: una planificada, para armarla; una cerrada, de solo lectura, con lo hecho y adónde fue lo demás.`],[`Una tarea`,`Tocándola se abre a la derecha: el detalle, la iteración y la columna, la prioridad (urgente y alta se marcan en la tarjeta), la estimación en puntos, quién la hace y el pedido del cliente del que salió. Cada tarea tiene un número (#12) que no se repite, para nombrarla en los commits.`],[`Respuestas del cliente`,`Los pedidos de su portal que son de este proyecto (los del mismo roadmap o sitio, y los generales del cliente), con el último mensaje y si te esperan; «Crear tarea» suma uno al backlog atado al pedido. Además, el presupuesto del que salió.`],[`Roadmap del portal`,`Es el roadmap que ve el cliente para este proyecto, el mismo de su ficha. Desde acá sumás etapas, entregás, publicás y lo ves como el cliente, sin salir del proyecto. Cada etapa muestra la iteración que la entrega. Si todavía no tiene, «Crear el roadmap» lo arma con los datos del proyecto, o elegí en «Atar uno que ya existe…» uno del cliente.`],[`Notas`,`Lo que hay que tener en cuenta: acuerdos, decisiones, pendientes. Las ven los dos, con quién la escribió y cuándo. Se pueden fijar arriba, editar (queda «editada») y borrar.`]]},{id:`presupuestos`,title:`Presupuestos`,items:[[`Armar uno`,`Desde una consulta («Armar presupuesto») o en Negocio → Presupuestos → «Nuevo presupuesto». Para quién (un cliente nuevo, que se crea si lo acepta, o uno que ya tenés, con su sitio), el nombre del proyecto, las etapas (qué se entrega, cuánto lleva o para qué fecha, y el precio; las flechas cambian el orden), la moneda, la seña (porcentaje o monto) y en cuántas cuotas va el saldo, el mantenimiento (mensual fijo, consumo de Railway o ninguno), hasta cuándo vale y las condiciones. A la derecha ves cómo lo va a ver el cliente.`],[`Mandarlo`,`«Enviar» le manda al cliente un mail con el enlace (te pregunta si estás seguro). Si ese mail no está en la ficha del cliente, por ejemplo con un cliente nuevo, te pide el código de 6 dígitos. «Copiar link» copia el mismo enlace para mandarlo por WhatsApp; si era un borrador, queda como enviado. Un borrador nunca se ve con el enlace.`],[`Estados`,`Borrador, Enviado, Visto (lo abrió y no respondió: el número del menú cuenta estos), Aceptado, Rechazado y Vencido. Arriba ves cuándo se mandó, cuántas veces lo abrió y la última.`],[`Cambiarlo después de mandarlo`,`Mientras no lo respondió, lo podés cambiar y guardar: el cliente ve la versión nueva al abrir el enlace, y si lo tenía abierto le pide recargar antes de aceptar. Si venció, cambiá «Válido hasta» y guardá: vuelve a estar abierto. Uno aceptado o rechazado ya no cambia (solo las notas internas); para otra propuesta, «Duplicar».`],[`Qué ve el cliente`,`Las etapas sobre una regla de tiempo, el total, cómo se paga (la seña al arrancar y las cuotas mes a mes; las fechas, recién cuando lo activás), el mantenimiento, la validez y las condiciones. Nunca tus notas internas, ni su mail, ni la consulta. Lo acepta con su nombre y «Acepto», o lo rechaza con un motivo si quiere.`],[`Cuando lo acepta`,`Te llega un aviso al celular y un mail, y al cliente la confirmación con cómo se paga y «Cómo pagar». La consulta queda «Ganada» y el presupuesto, «Aceptado, falta activar». Todavía no se crea nada: ni el cliente, ni los cobros, ni el roadmap en su portal.`],[`Activarlo`,`Cuando arranca el trabajo, abrí el presupuesto y tocá «Activar». Se crea todo, una sola vez y con las fechas desde ese día: el cliente (si no existía; si ya hay uno con el mismo mail, se usa ese), el sitio (uno nuevo sin direcciones si no elegiste uno: completalas en Ajustes cuando se publique), el contrato con el total de las etapas, la seña (vence a los 10 días) y las cuotas como cobros pendientes, el mensual desde el mes siguiente a la entrega estimada, un roadmap publicado con una etapa planificada por cada etapa del presupuesto (lo ve en su portal cuando le des una cuenta) y su proyecto en Proyectos.`],[`Si lo rechaza`,`Te llega el aviso con el motivo, si lo escribió. No se crea nada.`]]},{id:`portal`,title:`Roadmaps y portal de clientes`,items:[[`Qué es`,`Cada cliente puede entrar a su portal (la dirección está en su ficha, en «Portal del cliente») y ver sus próximas reuniones con el botón para entrar, el plan de entregas de sus proyectos, lo que ya le entregaste con notas, enlaces y archivos, y el estado de su servicio. Ve solo lo suyo y nunca entra al panel. Lo ve en el idioma del cliente (Castellano o English, en su ficha); antes de entrar, en el idioma de su navegador, y con el botón de arriba lo cambia a mano.`],[`Armar un roadmap`,`En la ficha del cliente → Roadmaps → «Nuevo roadmap», o en la página del proyecto → «Crear el roadmap». Elegí el proyecto del panel y se completan el nombre, el resumen y el sitio. El nombre es el que ve el cliente y lo podés cambiar. Arranca como borrador.`],[`Etapas`,`«Agregar etapa»: qué se entrega, qué incluye y la fecha estimada. Cada una está Planificada, En curso o Entregada. Las flechas cambian el orden en que las ve el cliente.`],[`Entregar`,`«Entregar» en una etapa la marca como entregada (con la fecha de hoy si no elegís otra) y te deja escribir la nota de la entrega, sumar enlaces (una demo, un video) y subir archivos de hasta 50 MB. Los archivos se guardan al subirlos y el cliente los baja al tocarlos, con un enlace que vence al minuto.`],[`Publicar`,`«Publicar» hace que el cliente vea el roadmap en su portal; «Despublicar» se lo oculta. Los borradores no los ve nunca. Te pregunta si estás seguro en los dos casos.`],[`Darle acceso`,`En «Portal del cliente» → «Cuenta»: su nombre y su mail (te pide el código de 6 dígitos). Le llega un mail con el enlace al portal y una contraseña temporal, que también ves una sola vez para pasársela por otro medio. Al entrar, elige su propia contraseña. Puede tener varias cuentas (por ejemplo, el dueño y la secretaria).`],[`Desactivar o contraseña nueva`,`«Desactivar» lo saca del portal al instante; «Reactivar» le devuelve el acceso. «Contraseña nueva» le manda otra temporal si se olvidó la suya. Solo vos (el dueño del panel) manejás las cuentas.`],[`Editar nombre o mail`,`«Editar» cambia el nombre y el mail con el que entra (te pide el código). Si cambiás el mail, la contraseña que tenía deja de andar, quien tenga el portal abierto con el mail anterior sale y le llega una temporal nueva al mail nuevo.`],[`Qué ve del servicio`,`Por cada sitio: si funciona, tiene demoras, está fuera de servicio, en mantenimiento o en preparación (un sitio en desarrollo no aparece); la disponibilidad de los últimos 30 días; cuándo fue la última copia de seguridad y su plan (abono mensual, según uso o pago único). Nunca montos, incidentes, datos de Railway ni nada de las compus de respaldo.`],[`Pedidos`,`En su portal, «Pedidos» → «Nuevo pedido»: elige si es un cambio, un problema o una consulta, sobre qué proyecto o sitio, un título, lo cuenta y suma hasta 5 capturas o PDF de 5 MB (arrastrándolas, eligiéndolas o pegándolas con Ctrl+V; nada de SVG ni otros archivos). Ve el estado (recibido, en curso, esperando su respuesta, resuelto), responde y puede cerrarlo. Si lo sumaste al roadmap, ve en qué etapa quedó. Como mucho 20 pedidos y 100 mensajes por día por cuenta.`],[`Ver como el cliente`,`En la ficha del cliente, en cada roadmap y en la página del proyecto abre su portal entero tal cual lo ve él, con tu sesión del panel: resumen, roadmaps con sus entregas, notas, enlaces y archivos, estado del servicio y pedidos. Es de solo lectura: desde ahí no se manda nada. Si todavía no tiene cuenta del portal, el saludo usa la persona de contacto. Se ve en el idioma del cliente, como lo ve él. «Incluir lo no publicado» muestra también los roadmaps en borrador, marcados «No publicado», para revisarlos antes de publicar. Desde un roadmap en borrador se abre ya prendido. «Volver al panel» te lleva a la ficha.`]]},{id:`estudio`,title:`Estudio`,items:[[`Portfolio`,`Los proyectos de la página pública. Solo se ven los publicados. El seguimiento del desarrollo está en Negocio → Proyectos.`],[`Proyectos en inglés`,`En cada proyecto, la sección «Inglés» tiene los textos, las características, la ficha y los epígrafes para la versión en inglés del sitio. Lo que dejes vacío se muestra en castellano.`],[`Plantillas`,`Qué plantillas se muestran en la vidriera y los pedidos que llegan. «Armar cliente con este pedido» genera en la PC de Ignacio la carpeta del cliente con todo lo que eligió. Los pedidos nuevos suman al contador del menú hasta que abrís la página; «Borrar» saca el pedido y sus imágenes.`],[`Notas`,`Notas sueltas y por cliente.`],[`Ajustes`,`Cotización del dólar (automática o a mano), presupuesto total de Railway, meta mensual y datos del estudio. «Importar copia» puede pedirte el código de 6 dígitos.`]]},{id:`codigo`,title:`Código`,items:[[`Qué es`,`Estudio → Código: el historial de git y las ramas de cada proyecto, como están en las compus. Lo manda el agente de cada PC (no hay ninguna cuenta de GitHub conectada al panel): encuentra solo los repos de su carpeta de proyectos, cada 10 minutos mira si cambió algo y sube solo lo nuevo. Nunca sube las carpetas.`],[`La lista`,`Cada proyecto con el sitio al que corresponde (si es de un sitio), el enlace a su repo, la rama sacada, el último commit y cuántas ramas tiene, del commit más nuevo al más viejo. Un repo sin remoto dice «Solo en la PC». Varios clones del mismo repo, en una PC o en varias, son un solo proyecto.`],[`Un proyecto`,`El gráfico de ramas al lado de los commits: cada rama con su color, las curvas donde nace una rama y donde se une (los merges tienen el punto hueco), y en cada commit sus etiquetas: la rama sacada con HEAD, ↑ los commits sin subir y ↓ los del remoto sin bajar, la rama del remoto con un globito y las versiones. «Todas las ramas» filtra por una sola y el buscador marca los commits cuyo mensaje, autor o código coincide. Tocá un commit para ver el código entero (con «Copiar»), sus padres, la fecha, cuántos archivos cambió y el enlace al commit en GitHub.`],[`Otras ramas`,`Las ramas de pruebas que ya se unieron a otra no ensucian el gráfico: van abajo, en «Otras ramas».`],[`Actualizar`,`Le pide a la primera compu prendida que lo lea todo ya mismo, sin esperar los 10 minutos. Durante un lockdown está deshabilitado (mirar, se puede).`],[`PC apagada`,`Si la PC está apagada lo dice arriba: lo que ves es lo último que mandó, y se pone al día sola cuando la prendés. Lo que ninguna PC vuelve a mandar en 30 días se borra solo.`],[`Varias PCs`,`Si un proyecto está en más de una PC, arriba elegís de cuál verlo; por defecto, la que tiene el commit más nuevo.`],[`Otra carpeta o una PC nueva`,`La carpeta de proyectos se elige al instalar el agente (con la ventana de Windows) y se puede cambiar después. Los nombres salen del sitio o del repo, nunca del nombre de la carpeta; desde la configuración del agente se puede esconder un repo o ponerle otro nombre.`]]},{id:`solo`,title:`Lo que el panel hace solo`,items:[[`Cada minuto`,`Chequea cada sitio y recibe sus latidos.`],[`Cada 10 minutos`,`Cada compu mira si cambió algo en los repos de sus proyectos y manda lo nuevo a Código.`],[`Cada 2 horas`,`Hace las copias de cada base.`],[`Todos los días`,`Revisa certificados y dominios (avisa con 20 días), actualiza el dólar, controla el gasto de Railway contra el presupuesto, manda los recordatorios de pago activados y guarda una copia de la base del panel. La PC de Ignacio arma la bóveda.`],[`Los domingos`,`Prueba restaurar una copia en una compu de respaldo.`],[`El día 1`,`Genera los cobros mensuales de los contratos (los de pago único, nunca), te manda el resumen por mail y arma los borradores de los informes a clientes.`]]}];function c(){return n(`Guía de uso`),(0,o.jsxs)(`div`,{className:`stack`,children:[(0,o.jsx)(a,{title:`Guía de uso`,description:`Qué hay en cada pantalla y qué hace el panel solo.`}),(0,o.jsxs)(e,{to:`/admin/guia/seguridad`,className:`guide-secure`,children:[(0,o.jsx)(t,{name:`shield`,size:20}),(0,o.jsxs)(`span`,{children:[(0,o.jsx)(`strong`,{children:`Seguridad y recuperación`}),(0,o.jsx)(`small`,{children:`Cómo está protegida cada cosa y qué hacer si perdés el celular, la PC o el acceso a algo. Te pide el código de 6 dígitos.`})]})]}),(0,o.jsx)(`nav`,{className:`guide-toc`,"aria-label":`Secciones de la guía`,children:s.map(e=>(0,o.jsx)(`a`,{href:`#${e.id}`,children:e.title},e.id))}),s.map(e=>(0,o.jsx)(`section`,{id:e.id,className:`guide-section`,children:(0,o.jsx)(i,{title:e.title,children:(0,o.jsx)(`dl`,{className:`guide-list`,children:e.items.map(([e,t])=>(0,o.jsxs)(`div`,{children:[(0,o.jsx)(`dt`,{children:e}),(0,o.jsx)(`dd`,{children:t})]},e))})})},e.id)),(0,o.jsxs)(`p`,{className:`small muted`,children:[`¿Algo no está acá o cambió? Pedíselo a Claude: la guía vive en `,(0,o.jsx)(`code`,{children:`src/admin/Guide.jsx`}),`. Para volver al inicio, `,(0,o.jsx)(e,{to:`/admin`,children:`Resumen`}),`.`]})]})}export{c as default};